'use client';
import { type ReactNode, type ButtonHTMLAttributes } from 'react';
type Variant = 'primary' | 'secondary' | 'ghost' | 'danger';
type Size = 'sm' | 'md' | 'lg';
interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> { variant?: Variant; size?: Size; children: ReactNode; }
const variants: Record<Variant, string> = { primary: 'bg-neutral-900 text-white hover:bg-neutral-800 shadow-sm', secondary: 'bg-white text-neutral-700 border border-neutral-200 hover:bg-neutral-50', ghost: 'text-neutral-600 hover:bg-neutral-100', danger: 'bg-red-600 text-white hover:bg-red-700' };
const sizes: Record<Size, string> = { sm: 'px-3 py-1.5 text-sm', md: 'px-4 py-2 text-sm', lg: 'px-5 py-2.5 text-base' };
export function Button({ variant = 'secondary', size = 'md', className = '', children, ...props }: ButtonProps) { return <button className={`inline-flex items-center justify-center gap-2 rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed ${variants[variant]} ${sizes[size]} ${className}`} {...props}>{children}</button>; }
